<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Slot Management | C-Net Library</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;background:#f3f6f8;color:#172033}.wrap{max-width:1450px;margin:28px auto;padding:0 18px}.top,.actions,.inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;align-items:flex-start;margin-bottom:18px}.btn{border:0;border-radius:8px;padding:9px 12px;background:#102a43;color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.green{background:#0f766e}.red{background:#b91c1c}.light{background:#e2e8f0;color:#102a43}.card{background:#fff;border:1px solid #dfe7ed;border-radius:14px;padding:18px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.field label{display:block;font-size:12px;font-weight:800;color:#52677a;margin-bottom:5px}.field input,.field select{width:100%;padding:9px;border:1px solid #cbd5e1;border-radius:8px}.muted{color:#64748b;font-size:13px}.alert{padding:12px;border-radius:9px;margin-bottom:14px}.ok{background:#ecfdf5}.err{background:#fef2f2}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:1100px}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;vertical-align:top;font-size:13px}th{background:#f8fafc;color:#52677a}.inline input,.inline select{padding:7px;border:1px solid #cbd5e1;border-radius:7px}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#dcfce7;font-weight:800}.off{background:#fee2e2}.warn{background:#fff7ed;padding:8px;border-radius:8px;margin-top:7px}@media(max-width:750px){.grid{grid-template-columns:1fr}.top{flex-direction:column}}</style></head><body><div class="wrap"><div class="top"><div><h1 style="margin:0">Slot Management</h1><div class="muted">Create, edit, clear timing, make flexibl